(function() {
  'use strict';

  // State management
  const state = {
    activeView: 'accounts',
    tierFilter: 'All',
    industryFilter: 'All',
    accountSearchTerm: '',
    stageFilter: 'All',
    priorityFilter: 'All',
    opportunitySearchTerm: '',
    accounts: [
      { id: '001', name: 'Acme Corporation', tier: 'Tier 1', industry: 'Technology', healthScore: 85, contractValue: '$500,000', opportunityCount: '5' },
      { id: '002', name: 'Global Industries', tier: 'Tier 2', industry: 'Manufacturing', healthScore: 72, contractValue: '$350,000', opportunityCount: '3' },
      { id: '003', name: 'HealthTech Solutions', tier: 'Tier 1', industry: 'Healthcare', healthScore: 91, contractValue: '$750,000', opportunityCount: '7' },
      { id: '004', name: 'Finance Corp', tier: 'Tier 2', industry: 'Finance', healthScore: 78, contractValue: '$425,000', opportunityCount: '4' },
      { id: '005', name: 'Retail Dynamics', tier: 'Tier 3', industry: 'Retail', healthScore: 65, contractValue: '$200,000', opportunityCount: '2' }
    ],
    opportunities: [
      { id: 'opp001', name: 'Enterprise Platform Upgrade', accountName: 'Acme Corporation', stageName: 'Proposal', amount: '$250,000', closeDate: '12/31/2024', priority: 'High' },
      { id: 'opp002', name: 'Cloud Migration Services', accountName: 'Global Industries', stageName: 'Negotiation', amount: '$180,000', closeDate: '11/15/2024', priority: 'High' },
      { id: 'opp003', name: 'Healthcare Analytics Suite', accountName: 'HealthTech Solutions', stageName: 'Qualification', amount: '$420,000', closeDate: '01/30/2025', priority: 'Medium' },
      { id: 'opp004', name: 'Security Compliance Package', accountName: 'Acme Corporation', stageName: 'Prospecting', amount: '$95,000', closeDate: '02/28/2025', priority: 'Low' },
      { id: 'opp005', name: 'Data Warehouse Implementation', accountName: 'Finance Corp', stageName: 'Proposal', amount: '$310,000', closeDate: '12/15/2024', priority: 'High' }
    ]
  };

  // Initialize on DOM ready
  function init() {
    setupEventListeners();
    renderAccounts();
    renderOpportunities();
  }

  function setupEventListeners() {
    // View toggle buttons
    const btnAccounts = document.getElementById('btnAccounts');
    const btnOpportunities = document.getElementById('btnOpportunities');

    if (btnAccounts) {
      btnAccounts.addEventListener('click', handleViewAccounts);
    }
    if (btnOpportunities) {
      btnOpportunities.addEventListener('click', handleViewOpportunities);
    }

    // Account filters
    const tierFilter = document.getElementById('tierFilter');
    const industryFilter = document.getElementById('industryFilter');
    const accountSearch = document.getElementById('accountSearch');

    if (tierFilter) {
      tierFilter.addEventListener('change', handleTierChange);
    }
    if (industryFilter) {
      industryFilter.addEventListener('change', handleIndustryChange);
    }
    if (accountSearch) {
      accountSearch.addEventListener('input', handleAccountSearch);
    }

    // Opportunity filters
    const stageFilter = document.getElementById('stageFilter');
    const priorityFilter = document.getElementById('priorityFilter');
    const opportunitySearch = document.getElementById('opportunitySearch');

    if (stageFilter) {
      stageFilter.addEventListener('change', handleStageChange);
    }
    if (priorityFilter) {
      priorityFilter.addEventListener('change', handlePriorityChange);
    }
    if (opportunitySearch) {
      opportunitySearch.addEventListener('input', handleOpportunitySearch);
    }

    // Account card clicks
    document.addEventListener('click', function(e) {
      const accountCard = e.target.closest('.account-card');
      if (accountCard) {
        const accountId = accountCard.getAttribute('data-id');
        console.log('Navigate to account:', accountId);
      }

      const opportunityRow = e.target.closest('.opportunity-row');
      if (opportunityRow) {
        const opportunityId = opportunityRow.getAttribute('data-id');
        console.log('Navigate to opportunity:', opportunityId);
      }
    });
  }

  function handleViewAccounts() {
    state.activeView = 'accounts';
    updateViewToggle();
    showAccountsView();
  }

  function handleViewOpportunities() {
    state.activeView = 'opportunities';
    updateViewToggle();
    showOpportunitiesView();
  }

  function updateViewToggle() {
    const btnAccounts = document.getElementById('btnAccounts');
    const btnOpportunities = document.getElementById('btnOpportunities');

    if (state.activeView === 'accounts') {
      btnAccounts.className = 'slds-button slds-button_brand';
      btnOpportunities.className = 'slds-button slds-button_neutral';
    } else {
      btnAccounts.className = 'slds-button slds-button_neutral';
      btnOpportunities.className = 'slds-button slds-button_brand';
    }
  }

  function showAccountsView() {
    const accountsView = document.getElementById('accountsView');
    const opportunitiesView = document.getElementById('opportunitiesView');

    if (accountsView) accountsView.style.display = 'block';
    if (opportunitiesView) opportunitiesView.style.display = 'none';
  }

  function showOpportunitiesView() {
    const accountsView = document.getElementById('accountsView');
    const opportunitiesView = document.getElementById('opportunitiesView');

    if (accountsView) accountsView.style.display = 'none';
    if (opportunitiesView) opportunitiesView.style.display = 'block';
  }

  function handleTierChange(event) {
    state.tierFilter = event.target.value;
    renderAccounts();
  }

  function handleIndustryChange(event) {
    state.industryFilter = event.target.value;
    renderAccounts();
  }

  function handleAccountSearch(event) {
    state.accountSearchTerm = event.target.value.toLowerCase();
    renderAccounts();
  }

  function handleStageChange(event) {
    state.stageFilter = event.target.value;
    renderOpportunities();
  }

  function handlePriorityChange(event) {
    state.priorityFilter = event.target.value;
    renderOpportunities();
  }

  function handleOpportunitySearch(event) {
    state.opportunitySearchTerm = event.target.value.toLowerCase();
    renderOpportunities();
  }

  function renderAccounts() {
    const accountsList = document.getElementById('accountsList');
    if (!accountsList) return;

    let filteredAccounts = state.accounts.filter(account => {
      const matchesTier = state.tierFilter === 'All' || account.tier === state.tierFilter;
      const matchesIndustry = state.industryFilter === 'All' || account.industry === state.industryFilter;
      const matchesSearch = !state.accountSearchTerm || account.name.toLowerCase().includes(state.accountSearchTerm);
      return matchesTier && matchesIndustry && matchesSearch;
    });

    if (filteredAccounts.length === 0) {
      accountsList.innerHTML = '<div class="slds-col slds-size_1-of-1"><div class="slds-text-align_center slds-p-vertical_large"><p>No accounts found</p></div></div>';
      return;
    }

    accountsList.innerHTML = filteredAccounts.map(account => `
      <div class="slds-col slds-size_1-of-1 slds-medium-size_1-of-2 slds-large-size_1-of-3">
        <div class="account-card" data-id="${account.id}">
          <div class="slds-text-heading_medium">${account.name}</div>
          <div class="slds-text-body_small slds-text-color_weak slds-m-top_xx-small">
            Tier: ${account.tier} | Industry: ${account.industry}
          </div>
          <div class="slds-grid slds-grid_vertical-align-center slds-m-top_small">
            <div class="slds-col">
              <div class="slds-text-body_small">Health Score: ${account.healthScore}</div>
              <div class="slds-text-body_small">Contract Value: ${account.contractValue}</div>
            </div>
          </div>
          <div class="slds-m-top_small">
            <span class="slds-badge">${account.opportunityCount}</span>
            <span class="slds-m-left_x-small">Opportunities</span>
          </div>
        </div>
      </div>
    `).join('');
  }

  function renderOpportunities() {
    const opportunitiesTable = document.getElementById('opportunitiesTable');
    if (!opportunitiesTable) return;

    let filteredOpportunities = state.opportunities.filter(opp => {
      const matchesStage = state.stageFilter === 'All' || opp.stageName === state.stageFilter;
      const matchesPriority = state.priorityFilter === 'All' || opp.priority === state.priorityFilter;
      const matchesSearch = !state.opportunitySearchTerm || opp.name.toLowerCase().includes(state.opportunitySearchTerm);
      return matchesStage && matchesPriority && matchesSearch;
    });

    if (filteredOpportunities.length === 0) {
      opportunitiesTable.innerHTML = '<tr><td colspan="6" class="slds-text-align_center slds-p-vertical_large">No opportunities found</td></tr>';
      return;
    }

    opportunitiesTable.innerHTML = filteredOpportunities.map(opp => `
      <tr class="opportunity-row" data-id="${opp.id}">
        <td data-label="Name">
          <div class="slds-truncate" title="${opp.name}">${opp.name}</div>
        </td>
        <td data-label="Account">
          <div class="slds-truncate" title="${opp.accountName}">${opp.accountName}</div>
        </td>
        <td data-label="Stage">
          <div class="slds-truncate" title="${opp.stageName}">${opp.stageName}</div>
        </td>
        <td data-label="Amount">
          <div class="slds-truncate">${opp.amount}</div>
        </td>
        <td data-label="Close Date">
          <div class="slds-truncate">${opp.closeDate}</div>
        </td>
        <td data-label="Priority">
          <span class="slds-badge">${opp.priority}</span>
        </td>
      </tr>
    `).join('');
  }

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

preview_css:
.summary-tile {
  padding: 1rem;
  background-color: #f3f3f3;
  border-radius: 0.25rem;
  text-align: center;
  height: 100%;
}

.account-card {
  padding: 1rem;
  border: 1px solid #dddbda;
  border-radius: 0.25rem;
  cursor: pointer;
  transition: box-shadow 0.2s ease-in-out, transform 0.2s ease-in-out;
  background-color: #ffffff;
  height: 100%;
}

.account-card:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
  transform: translateY(-2px);
}

.opportunity-row {
  cursor: pointer;
  transition: background-color 0.2s ease-in-out;
}

.opportunity-row:hover {
  background-color: #f3f3f3;
}

@media (max-width: 768px) {
  .summary-tile {
    margin-bottom: 0.5rem;
  }

  .account-card {
    margin-bottom: 0.5rem;
  }
}
